<?php declare(strict_types=1);namespace NpmGateway\Services;use NpmGateway\Contracts\ClockInterface;use NpmGateway\Repositories\MarketingFlyerNotificationOutboxRepository;use NpmGateway\Support\GatewayDateTimeFormatter;
final class MarketingFlyerNotificationHealthService{public function __construct(private readonly MarketingFlyerNotificationOutboxRepository$r,private readonly ClockInterface$clock){}public function check():array{$data=$this->r->health(MarketingFlyerNotificationWorker::NAME);$last=$data['heartbeat']['last_success_at']??null;$stale=!is_string($last)||$last===''||(new \DateTimeImmutable($last))<$this->clock->now()->modify('-5 minutes');$oldest=$data['oldest'];$age=$oldest===null?'none':$this->age(new \DateTimeImmutable((string)$oldest));return['healthy'=>!$stale,'stale'=>$stale,'last_success'=>$last===null?'never':GatewayDateTimeFormatter::format((string)$last),'pending'=>$data['counts']['pending'],'retry'=>$data['counts']['retry'],'failed'=>$data['counts']['failed'],'oldest_age'=>$age,'heartbeat_found'=>is_array($data['heartbeat'])];}private function age(\DateTimeImmutable$then):string{$seconds=max(0,$this->clock->now()->getTimestamp()-$then->getTimestamp());if($seconds<120)return$seconds.' seconds';if($seconds<7200)return(int)floor($seconds/60).' minutes';return(int)floor($seconds/3600).' hours';}}
